    /**
     * Handles deleting a Bank entity
     * @param		command ${class.getDeleteCommandAlias()}
     * @return		CompletableFuture<Void>
     */
    @DeleteMapping("/delete")    
    public CompletableFuture<Void> delete( @RequestBody(required=true) DeleteBankCommand command ) {                
    	CompletableFuture<Void> completableFuture = null;
    	try {
        	BankService delegate = service;

        	completableFuture = delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Bank with key " + command.getBankId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }
        
        return completableFuture;
	}        
	
    /**
     * Handles loading a Bank using a UUID
     * @param		UUID uuid 
     * @return		Bank
     */    
    @GetMapping("/load")
    public Bank load( @RequestParam(required=true) UUID uuid ) {    	
    	Bank entity = null;

    	try {  
    		entity = service.getBank( new BankFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Bank using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Bank business objects
     * @return		Set<Bank>
     */
    @GetMapping("/")
    public List<Bank> loadAll() {                
    	List<Bank> bankList = null;
        
    	try {
            // load the Bank
            bankList = service.getAllBank();
            
            if ( bankList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Banks" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Banks ", exc );
        	return null;
        }

        return bankList;
                            
    }


